from odoo import fields, models

class MailPushDevice(models.Model):
    _inherit = 'mail.push.device'

    keys = fields.Char(
        string='Browser keys',
        required=True,
        help=(
            "It refers to browser keys used by the notification: \n"
            "- p256dh: This is the subscription public key generated by the browser. "
            "The browser will keep the private key secret and use it for decrypting the payload.\n"
            "- auth: The auth value should be treated as a secret and not shared outside of Company"
        )
    )
